    $value = static function (string $key, mixed $fallback = null) use ($get, $record): mixed {
        if (isset($get) && is_callable($get)) return $get($key) ?? $fallback;
        return data_get($record, $key, $fallback);
    };
    $builder = $value('builder_data', $record?->builder_data ?? \App\Models\FoundationSkTemplate::defaultBuilderData()) ?: [];
    $header = $builder['header'] ?? []; $decision = $builder['decision'] ?? []; $sections = $builder['sections'] ?? [];
    $content = $value('content', $record?->content ?? ''); $customCss = $value('custom_css', $record?->custom_css ?? '');
    $size = $value('paper_size', $record?->paper_size ?? 'A4'); $orientation = $value('orientation', $record?->orientation ?? 'portrait');
    $logoPath = $header['logo_path'] ?? null;
    if (is_array($logoPath)) $logoPath = array_values($logoPath)[0] ?? null;
    if (filled($logoPath) && ! str_contains($logoPath, '/')) $logoPath = 'foundation-sk/logos/'.$logoPath;
    $logoUrl = filled($logoPath) && \Illuminate\Support\Facades\Storage::disk('public')->exists($logoPath)
        ? route('foundation-sk.template-asset', ['path' => $logoPath])
        : null;
    $dimensions = match ($size) { 'F4' => [816, 1248], 'Legal', 'LEGAL' => [816, 1344], 'LETTER' => [816, 1056], default => [794, 1123] };
    if ($orientation === 'landscape') $dimensions = [$dimensions[1], $dimensions[0]];
@endphp
